@page "/apply"
@using sv_d3a518bdc8e443ce9734b4b11f3a40fe.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (CurrentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="FullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="Email" placeholder="Enter your email address" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="Phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="Address" placeholder="Enter your address" />
            </div>
            <div class="form-actions">
                <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@IsValidating">
                    @(IsValidating ? "Validating..." : "Next")
                </button>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (CurrentStep == 1)
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (WorkEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="WorkEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="WorkEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="WorkEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <input type="checkbox" id="current-@index" @bind="WorkEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea @bind="WorkEntries[index].Description" placeholder="Describe your responsibilities and achievements"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (CurrentStep == 2)
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (References.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="References[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="References[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="References[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="References[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (References.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (CurrentStep == 3)
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" class="cover-letter-textarea" @bind="CoverLetter" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit for this role..."></textarea>
                <div class="character-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (CurrentStep == 4)
    {
        <div class="step-content">
            @if (IsSubmitted)
            {
                <div class="submission-confirmation">
                    <h2>Application Submitted!</h2>
                    <p>Your application has been successfully submitted.</p>
                    <p class="application-id">Application ID: <strong>@SubmittedApplicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <!-- Personal Info Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <a href="javascript:void(0)" class="edit-link" @onclick="() => GoToStep(0)">Edit</a>
                    </div>
                    <div class="review-content">
                        <p><strong>Name:</strong> @FullName</p>
                        <p><strong>Email:</strong> @Email</p>
                        <p><strong>Phone:</strong> @Phone</p>
                        <p><strong>Address:</strong> @Address</p>
                    </div>
                </div>

                <!-- Work History Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <a href="javascript:void(0)" class="edit-link" @onclick="() => GoToStep(1)">Edit</a>
                    </div>
                    <div class="review-content">
                        @foreach (var entry in WorkEntries)
                        {
                            <div class="review-work-entry">
                                <p><strong>@entry.Title</strong> at @entry.Company</p>
                                <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                                <p>@entry.Description</p>
                            </div>
                        }
                    </div>
                </div>

                <!-- References Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <a href="javascript:void(0)" class="edit-link" @onclick="() => GoToStep(2)">Edit</a>
                    </div>
                    <div class="review-content">
                        @foreach (var reference in References)
                        {
                            <div class="review-reference">
                                <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                                <p>@reference.Email | @reference.Phone</p>
                            </div>
                        }
                    </div>
                </div>

                <!-- Cover Letter Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <a href="javascript:void(0)" class="edit-link" @onclick="() => GoToStep(3)">Edit</a>
                    </div>
                    <div class="review-content">
                        <p class="cover-letter-preview">@CoverLetter</p>
                    </div>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
                        @(IsSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsValidating { get; set; }
    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1: Personal Info
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            ErrorMessage = string.Empty;
        }
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!isEmailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
            CurrentStep++;
        }
        finally
        {
            IsValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = string.Empty;

        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
            {
