.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    background-color: #4361ee;
    color: white;
    box-shadow: 0 0 0 4px rgba(67, 97, 238, 0.2);
}

.step.completed .step-circle {
    background-color: #2ec4b6;
    color: white;
}

.step.future .step-circle {
    background-color: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step.future .step-label {
    color: #999;
}

.checkmark {
    font-size: 1rem;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #e0e0e0;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
    min-width: 20px;
    max-width: 60px;
}

.step-connector.completed {
    background-color: #2ec4b6;
}

/* Form Content */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.75rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem 0.9rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 100px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #f0f0f0;
}

.btn-next,
.btn-back,
.btn-submit,
.btn-add,
.btn-remove {
    padding: 0.7rem 1.5rem;
    border: none;
    border-radius: 8px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-next {
    background-color: #4361ee;
    color: white;
    margin-left: auto;
}

.btn-next:hover:not(:disabled) {
    background-color: #3a56d4;
}

.btn-next:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-back {
    background-color: #f0f0f0;
    color: #333;
}

.btn-back:hover {
    background-color: #e0e0e0;
}

.btn-submit {
    background-color: #2ec4b6;
    color: white;
    padding: 0.8rem 2rem;
}

.btn-submit:hover:not(:disabled) {
    background-color: #25a99d;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background-color: #f8f9fa;
    color: #4361ee;
    border: 1px dashed #4361ee;
    width: 100%;
    margin-top: 1rem;
    padding: 0.8rem;
}

.btn-add:hover {
    background-color: #eef0ff;
}

.btn-remove {
    background-color: #fee;
    color: #dc3545;
    padding: 0.4rem 0.8rem;
    font-size: 0.85rem;
}

.btn-remove:hover {
    background-color: #fdd;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
