    border-radius: 8px;
    margin-bottom: 1rem;
    border: 1px solid #fcc;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
